739				result.Error = ErrToolCallLoop
740				result.Duration = time.Since(start)
741				snapshotMessages()
742				emitFinalSessionEnd(req.Callback, sessionID, &seq, req.Provider, &result, req.Metadata)
743				return result, ErrToolCallLoop
744			}
