909	// toolCallFingerprint returns a string that uniquely identifies a set of tool
910	// calls by name and arguments, in order. Used to detect identical consecutive turns.
911	func toolCallFingerprint(calls []ToolCall) string {
912		parts := make([]string, len(calls))
913		for i, c := range calls {
914			parts[i] = c.Name + "\x00" + string(c.Arguments)
915		}
916		return strings.Join(parts, "\x01")
917	}
